        let git = checkbox("new-project-git", "Initialize a Git repository")
            .checked(self.init_git)
            .on_click(cx.listener(|this, on: &bool, _, cx| {
                this.init_git = *on;
                cx.notify();
            }));

        let templates =
            v_flex()
                .id("new-project-templates")
